interface Agent {
  role: string;
  receive(msg: Message): Promise<void>;
  act(): Promise<Message | null>;
}

class Orchestrator {
  private agents: Agent[];
  async dispatch(task: Task) {
    const plan = await this.planner.act(task);
    for (const step of plan.steps) {
      const agent = this.agents.find(a => a.role === step.role)!;
      const out = await agent.receive(step);
      if (out) await this.broadcast(out);
    }
  }
  async broadcast(msg: Message) {
    await Promise.all(this.agents.map(a => a.receive(msg)));
  }
}
